function CLASSIFY_ALL_DCM_REPORTS_LOO()
% CLASSIFY_ALL_DCM_REPORTS_LOO
%
% Reads all Excel reports generated by the first-level DCM between-group stats,
% selects exploratory feature panels from each report, extracts those features
% for each subject directly from DCM.Ep, then performs leave-one-out (LOO)
% classification using:
%   1) Linear SVM
%   2) RBF SVM
%   3) Random Forest
%   4) AdaBoost Tree Ensemble
%
% -------------------------------------------------------------------------
% Feature selection here is treated as EXPLORATORY and
% ranking-based, rather than thresholding on corrected significance.
%
% Implemented feature selection rules:
%   A) P_TOP5 / P_TOP10:
%      rank by smallest uncorrected p-value
%
%   B) D_TOP5 / D_TOP10:
%      rank by largest absolute Cohen's d
%
%   C) COMBINED_TOP5 / COMBINED_TOP10:
%      rank by z(-log10 p) + z(|d|)
%
%   D) STABLE_TOP5 / STABLE_TOP10:
%      same combined score + recurrence bonus across all reports
%
% -------------------------------------------------------------------------
% REQUIRED TOOLBOXES
% -------------------------------------------------------------------------
% - SPM on MATLAB path (spm_vec, spm_fieldindices)
% - Statistics and Machine Learning Toolbox
%
% -------------------------------------------------------------------------
% OUTPUTS
% -------------------------------------------------------------------------
% Creates a folder:
%   results/dcm_probe/
%
% Inside:
%   /<comparison_name>/
%       SelectedFeatures_<panel>.xlsx
%       Classification_<panel>.xlsx
%       /figures/
%           ROC_*.png
%           Confusion_*.png
%           ROC_AllModels.png
%
% Also creates:
%   results/dcm_probe/Summary_AllComparisons.xlsx
%
% -------------------------------------------------------------------------

clc; close all; clearvars;

% Local folders: edit these paths to match your data.
repoRoot = fileparts(fileparts(mfilename('fullpath')));
dataRoot = fullfile(repoRoot, 'data');
resultsRoot = fullfile(repoRoot, 'results');


%% ====================== USER SETTINGS ===========================

excelFolder = dataRoot;
excelFile = 'participants.xlsx';
excelPath   = fullfile(excelFolder, excelFile);

matFolder = fullfile(resultsRoot, 'dcm');
matPattern  = '*_DCM_DSALL.mat';

statsDirCandidates = {fullfile(resultsRoot, 'dcm_statistics')};

rngSeed   = 1;
nTreesRF  = 300;
nTreesAda = 200;

panelSizes = [5 10];
minPanelSize = 2;

makeFigures = false;
removePlotGrids = true; %#ok<NASGU>

outRoot = fullfile(resultsRoot, 'dcm_probe');
if ~exist(outRoot, 'dir'), mkdir(outRoot); end

%% ====================== STEP 1: RESOLVE STATS DIR =====================

statsDir = '';
for i = 1:numel(statsDirCandidates)
    if exist(statsDirCandidates{i}, 'dir')
        statsDir = statsDirCandidates{i};
        break;
    end
end

if isempty(statsDir)
    error('Could not find STAT_FRIST_LEVEL_DCM folder. Please edit statsDirCandidates.');
end

fprintf('Using statsDir:\n%s\n', statsDir);

reportFiles = dir(fullfile(statsDir, '*.xlsx'));
if isempty(reportFiles)
    error('No Excel reports found in %s', statsDir);
end

%% ====================== STEP 2: LOAD LABEL EXCEL ======================

if ~isfile(excelPath)
    error('Excel file not found: %s', excelPath);
end

data = readtable(excelPath);

IDs    = data{:,1};
Groups = data{:,2};

if isstring(IDs),    IDs    = cellstr(IDs); end
if isnumeric(IDs),   IDs = arrayfun(@(n) sprintf('Sub%04d', n), IDs, 'UniformOutput', false); end
if isstring(Groups), Groups = cellstr(Groups); end

IDs = regexprep(IDs, '^sub-', '');
IDs = regexprep(IDs, '.*?(Sub0*\d+).*', '$1');
Groups = cellfun(@(x) char(x), Groups, 'UniformOutput', false);
Groups = cellfun(@canonical_group_label, Groups, 'UniformOutput', false);

%% ====================== STEP 3: LIST DCM FILES ========================

allFiles = dir(fullfile(matFolder, matPattern));
matNames = {allFiles.name}';

tok  = regexp(matNames, '^(Sub0\d+)_DCM_DSALL\.mat$', 'tokens', 'once');
keep = ~cellfun('isempty', tok);

matNames = matNames(keep);
matIDs   = cellfun(@(c) c{1}, tok(keep), 'UniformOutput', false);

if isempty(matNames)
    error('No DCM files matching pattern found in %s', matFolder);
end

%% ====================== STEP 4: MAP SUBJECTS ==========================

subj = struct('id', {}, 'label', {}, 'file', {});
k = 0;

for i = 1:numel(matIDs)
    thisID = matIDs{i};
    idx = find(strcmpi(IDs, thisID), 1, 'first');

    if isempty(idx)
        warning('No group found for ID %s (file %s). Skipping.', thisID, matNames{i});
        continue;
    end

    k = k + 1;
    subj(k).id    = thisID;
    subj(k).label = Groups{idx};
    subj(k).file  = fullfile(matFolder, matNames{i});
end

if isempty(subj)
    error('No subjects could be matched between label Excel and MAT files.');
end

% keep only CON, bvFTD and PSP subjects. PC and legacy mixed labels are excluded.
allMatchedLabels = {subj.label}';
keepPSPOnlySubjects = ismember(allMatchedLabels, {'CON','bvFTD','PSP'});
nExcludedPC = sum(~keepPSPOnlySubjects);
if nExcludedPC > 0
    fprintf('Excluding %d PC / legacy PC+PSP subjects from PSP-only analysis.\n', nExcludedPC);
end
subj = subj(keepPSPOnlySubjects);

if isempty(subj)
    error('After PSP-only filtering, no usable CON/bvFTD/PSP subjects remain.');
end

print_group_counts({subj.label}');

%% ====================== STEP 5: REFERENCE PARAMETERISATION ============

refNames = [];
np_ref   = [];
refOK    = false;

for i = 1:numel(subj)
    if ~isfile(subj(i).file), continue; end

    S = load(subj(i).file);
    if ~isfield(S,'DCM') || ~isfield(S.DCM,'Ep')
        warning('No DCM.Ep in %s. Skipping.', subj(i).file);
        continue;
    end

    DCM = S.DCM;
    Ep_vec = spm_vec(DCM.Ep);
    np     = numel(Ep_vec);

    try
        nm = spm_fieldindices(DCM.Ep, 1:np);
    catch
        nm = arrayfun(@(j) sprintf('p_%04d', j), 1:np, 'UniformOutput', false);
        warning('spm_fieldindices failed for %s. Using fallback names.', subj(i).id);
    end

    if isstring(nm), nm = cellstr(nm); end
    if ~iscell(nm),  nm = cellstr(string(nm)); end

    refNames = nm(:);
    np_ref   = np;
    refOK    = true;
    break;
end

if ~refOK
    error('Could not establish reference DCM parameter names.');
end

%% ====================== STEP 6: EXTRACT FULL PARAMETER MATRIX =========

Nsub = numel(subj);
Xall = nan(Nsub, np_ref);

for i = 1:Nsub
    if ~isfile(subj(i).file)
        warning('Missing file: %s', subj(i).file);
        continue;
    end

    S = load(subj(i).file);
    if ~isfield(S,'DCM') || ~isfield(S.DCM,'Ep')
        warning('No DCM.Ep in %s', subj(i).file);
        continue;
    end

    DCM = S.DCM;
    Ep_vec = spm_vec(DCM.Ep);

    np = numel(Ep_vec);
    if np ~= np_ref
        warning('Param length mismatch for %s: np=%d, ref=%d. Trunc/pad with NaN.', ...
            subj(i).id, np, np_ref);
        m = min(np, np_ref);
        Xall(i,1:m) = Ep_vec(1:m);
    else
        Xall(i,:) = Ep_vec(:)';
    end
end

allNaN = all(isnan(Xall), 2);
if any(allNaN)
    warning('Removing %d subjects with no extracted parameters.', sum(allNaN));
    subj = subj(~allNaN);
    Xall = Xall(~allNaN,:);
    Nsub = numel(subj);
end

allLabels = {subj.label}';

%% ====================== STEP 7: READ ALL REPORTS ======================

reports = struct([]);
for r = 1:numel(reportFiles)
    reportPath = fullfile(reportFiles(r).folder, reportFiles(r).name);
    [~, reportBase, ~] = fileparts(reportFiles(r).name);

    if is_legacy_pc_report(reportBase)
        fprintf('Skipping legacy PC/PSP report: %s\n', reportFiles(r).name);
        continue;
    end

    try
        Tstats = readtable(reportPath, 'Sheet', 'Stats');
    catch
        warning('Could not read Stats sheet from %s. Skipping.', reportPath);
        continue;
    end

    try
        Tsum = readtable(reportPath, 'Sheet', 'Summary');
    catch
        warning('Could not read Summary sheet from %s. Skipping.', reportPath);
        continue;
    end

    if isempty(Tsum) || ~ismember('Comparison', Tsum.Properties.VariableNames)
        warning('Summary sheet malformed in %s. Skipping.', reportPath);
        continue;
    end

    rep = struct();
    rep.path       = reportPath;
    rep.baseName   = reportBase;
    rep.stats      = Tstats;
    rep.summary    = Tsum;

    rep.comparison = char(Tsum.Comparison{1});

    if is_legacy_pc_report(rep.comparison)
        fprintf('Skipping legacy PC/PSP comparison: %s\n', rep.comparison);
        continue;
    end

    rep.group1 = canonicalize_group_list(parse_group_labels(char(Tsum.Group1_Labels{1})));
    rep.group2 = canonicalize_group_list(parse_group_labels(char(Tsum.Group2_Labels{1})));

    if isempty(rep.group1) || isempty(rep.group2)
        warning('Skipping %s because group labels could not be resolved after PSP-only filtering.', reportFiles(r).name);
        continue;
    end

    if any(strcmp(rep.group1, 'PC')) || any(strcmp(rep.group2, 'PC')) || ...
       any(strcmp(rep.group1, 'PSPPC_EXCLUDED')) || any(strcmp(rep.group2, 'PSPPC_EXCLUDED'))
        fprintf('Skipping report containing PC/legacy PC+PSP labels: %s\n', reportFiles(r).name);
        continue;
    end

    reports = [reports; rep];
end

if isempty(reports)
    error('No usable PSP-only Excel reports found. Check that STAT_FRIST_LEVEL_DCM contains CON_vs_PSP / bvFTD_vs_PSP or equivalent PSP-only reports.');
end

fprintf('\nUsable PSP-only reports found: %d\n', numel(reports));
for rr = 1:numel(reports)
    fprintf('  %s: %s vs %s\n', reports(rr).comparison, strjoin(reports(rr).group1, ','), strjoin(reports(rr).group2, ','));
end

%% ====================== STEP 8: BUILD STABILITY BONUS =================

allFeatureNames = refNames(:);
nFeatures = numel(allFeatureNames);

recurrenceScore = zeros(nFeatures,1);
signConsistency = zeros(nFeatures,1); 
for r = 1:numel(reports)
    T = reports(r).stats;
    T = clean_stats_table(T);

    if isempty(T), continue; end

    [tf, idxRef] = ismember(T.ParamName, allFeatureNames);
    T = T(tf,:);
    idxRef = idxRef(tf);

    p = T.p_uncorrected;
    d = T.Cohens_d;

    lp = -log10(max(p, realmin));
    ad = abs(d);

    zlp = safe_zscore(lp);
    zad = safe_zscore(ad);

    comb = zlp + zad;

    [~, ord] = sort(comb, 'descend', 'MissingPlacement', 'last');
    ord = ord(1:min(20, numel(ord)));

    recurrenceScore(idxRef(ord)) = recurrenceScore(idxRef(ord)) + 1;

    sgn = sign(d);
    signConsistency(idxRef) = signConsistency(idxRef) + sgn;
end

if max(recurrenceScore) > 0
    recurrenceBonus = recurrenceScore / max(recurrenceScore);
else
    recurrenceBonus = zeros(size(recurrenceScore));
end

%% ====================== STEP 9: RUN EACH REPORT =======================

summaryMetricsAll = table();

for r = 1:numel(reports)

    compName = reports(r).comparison;
    Tstats   = clean_stats_table(reports(r).stats);
    g1       = reports(r).group1;
    g2       = reports(r).group2;

    fprintf('\n============================================================\n');
    fprintf('Processing comparison: %s\n', compName);
    fprintf('Group1: %s\n', strjoin(g1, ', '));
    fprintf('Group2: %s\n', strjoin(g2, ', '));
    fprintf('============================================================\n');

    idx1 = ismember(allLabels, g1);
    idx2 = ismember(allLabels, g2);

    if sum(idx1) < 2 || sum(idx2) < 2
        warning('%s skipped: need at least 2 subjects in each group.', compName);
        continue;
    end

    [tf, idxRef] = ismember(Tstats.ParamName, refNames);
    Tstats = Tstats(tf,:);
    idxRef = idxRef(tf);

    if isempty(Tstats)
        warning('%s skipped: no valid overlapping parameters.', compName);
        continue;
    end

    p  = Tstats.p_uncorrected;
    d  = Tstats.Cohens_d;
    lp = -log10(max(p, realmin));
    ad = abs(d);

    score_p        = -p;
    score_d        = ad;
    score_combined = safe_zscore(lp) + safe_zscore(ad);
    score_stable   = score_combined + 0.50 * recurrenceBonus(idxRef);

    panelDefs = {};

    for kk = 1:numel(panelSizes)
        K = panelSizes(kk);

        panelDefs(end+1,:) = {sprintf('P_TOP%d', K),        rank_select(idxRef, score_p,        K, 'descend')}; 
        panelDefs(end+1,:) = {sprintf('D_TOP%d', K),        rank_select(idxRef, score_d,        K, 'descend')}; 
        panelDefs(end+1,:) = {sprintf('COMBINED_TOP%d', K), rank_select(idxRef, score_combined, K, 'descend')}; 
        panelDefs(end+1,:) = {sprintf('STABLE_TOP%d', K),   rank_select(idxRef, score_stable,   K, 'descend')}; 
    end

    compDir = fullfile(outRoot, matlab.lang.makeValidName(compName));
    if ~exist(compDir, 'dir'), mkdir(compDir); end

    % FIXED: properly typed empty table
    panelLog = table( ...
        cell(0,1), ...   % Comparison
        cell(0,1), ...   % Panel
        zeros(0,1), ...  % NumFeatures
        cell(0,1), ...   % FeatureList
        'VariableNames', {'Comparison','Panel','NumFeatures','FeatureList'});

    for pp = 1:size(panelDefs,1)
        panelName = panelDefs{pp,1};
        featIdx   = unique(panelDefs{pp,2}, 'stable');

        featIdx = featIdx(~isnan(featIdx));
        if numel(featIdx) < minPanelSize
            warning('%s / %s skipped: too few selected features.', compName, panelName);
            continue;
        end

        Xcmp = Xall(idx1 | idx2, featIdx);
        yText = allLabels(idx1 | idx2);
        sCmp  = subj(idx1 | idx2);

        Y = ismember(yText, g2);
        Y = double(Y(:));

        keepRows = ~any(isnan(Xcmp),2);
        Xcmp = Xcmp(keepRows,:);
        Y    = Y(keepRows);
        yText = yText(keepRows);
        sCmp = sCmp(keepRows);

        nPos = sum(Y==1);
        nNeg = sum(Y==0);

        if nPos < 2 || nNeg < 2
            warning('%s / %s skipped after NaN removal: too few subjects.', compName, panelName);
            continue;
        end

        selectedNames = refNames(featIdx);

        % save selected features
        featTable = table;
        featTable.SubjectID = {sCmp.id}';
        featTable.Group     = yText(:);

        for j = 1:numel(selectedNames)
            safeName = matlab.lang.makeValidName(selectedNames{j});
            featTable.(safeName) = Xcmp(:,j);
        end

        featXlsx = fullfile(compDir, sprintf('SelectedFeatures_%s.xlsx', panelName));
        writetable(featTable, featXlsx, 'Sheet', 'SelectedFeatures');

        featInfo = table((1:numel(selectedNames))', featIdx(:), selectedNames(:), ...
            'VariableNames', {'FeatureOrder','ParamIndex','ParamName'});
        writetable(featInfo, featXlsx, 'Sheet', 'FeatureInfo');

        featSummary = table;
        featSummary.Comparison    = {compName};
        featSummary.Panel         = {panelName};
        featSummary.Group1        = {strjoin(g1, ',')};
        featSummary.Group2        = {strjoin(g2, ',')};
        featSummary.NumSubjects   = height(featTable);
        featSummary.NumGroup1     = sum(Y==0);
        featSummary.NumGroup2     = sum(Y==1);
        featSummary.NumFeatures   = numel(selectedNames);
        writetable(featSummary, featXlsx, 'Sheet', 'Summary');

        % FIXED: append row safely
        newRow = table({compName}, {panelName}, numel(selectedNames), {strjoin(selectedNames, ', ')}, ...
            'VariableNames', {'Comparison','Panel','NumFeatures','FeatureList'});
        panelLog = [panelLog; newRow];

        [metricsTable, predTable, rocStruct] = run_models_loo( ...
            Xcmp, Y, yText, {sCmp.id}', panelName, compName, g1, g2, rngSeed, nTreesRF, nTreesAda);

        classXlsx = fullfile(compDir, sprintf('Classification_%s.xlsx', panelName));
        writetable(metricsTable, classXlsx, 'Sheet', 'Metrics');
        writetable(predTable, classXlsx, 'Sheet', 'Predictions');
        writetable(featInfo, classXlsx, 'Sheet', 'SelectedFeatures');

        modelNames = fieldnames(rocStruct);
        for mm = 1:numel(modelNames)
            modelName = modelNames{mm};
            rocTab = table(rocStruct.(modelName).fpr(:), rocStruct.(modelName).tpr(:), ...
                'VariableNames', {'FPR','TPR'});
            sheetName = safe_sheet_name(modelName);
            writetable(rocTab, classXlsx, 'Sheet', sheetName);
        end

        if makeFigures
            figDir = fullfile(compDir, 'figures', panelName);
            if ~exist(figDir, 'dir'), mkdir(figDir); end
            save_roc_and_confusion_figures(rocStruct, predTable, figDir, panelName, compName);
        end

        tmp = metricsTable;
        tmp.Comparison = repmat({compName}, height(tmp), 1);
        tmp.Panel      = repmat({panelName}, height(tmp), 1);
        summaryMetricsAll = [summaryMetricsAll; tmp];
    end

    if ~isempty(panelLog)
        writetable(panelLog, fullfile(compDir, 'PanelLog.xlsx'), 'Sheet', 'Panels');
    end
end

%% ====================== STEP 10: GLOBAL SUMMARY =======================

if ~isempty(summaryMetricsAll)
    summaryXlsx = fullfile(outRoot, 'Summary_AllComparisons.xlsx');
    writetable(summaryMetricsAll, summaryXlsx, 'Sheet', 'AllMetrics');

    [~, ord] = sortrows(summaryMetricsAll(:, {'Comparison','AUC'}), {'Comparison','AUC'}, {'ascend','descend'});
    Tsorted = summaryMetricsAll(ord,:);

    bestRows = false(height(Tsorted),1);
    comps = unique(Tsorted.Comparison, 'stable');
    for i = 1:numel(comps)
        idx = strcmp(Tsorted.Comparison, comps{i});
        ii = find(idx, 1, 'first');
        if ~isempty(ii), bestRows(ii) = true; end
    end

    Tbest = Tsorted(bestRows,:);
    writetable(Tbest, summaryXlsx, 'Sheet', 'BestByComparison');
end

fprintf('\nAll done.\nOutputs in:\n%s\n', outRoot);

end

%% =====================================================================
%% ============================ HELPERS =================================
%% =====================================================================


function lab = canonical_group_label(x)
% Canonical group labels for PSP-only analysis.
% PC is intentionally kept separate and is later excluded.

if isstring(x), x = char(x); end
if isnumeric(x), x = char(string(x)); end
if isempty(x), lab = ''; return; end

raw = char(x);
s = lower(strtrim(raw));
s = strrep(s, '+', '');
s = strrep(s, '/', '');
s = strrep(s, '-', '');
s = strrep(s, '_', '');
s = regexprep(s, '\s+', '');

switch s
    case {'con','control','controls','healthycontrol','healthycontrols'}
        lab = 'CON';
    case {'bvftd','bvfrontotemporaldementia','behaviouralvariantfrontotemporaldementia'}
        lab = 'bvFTD';
    case {'psp','progressivesupranuclearpalsy'}
        lab = 'PSP';
    case {'pc','cbs','corticobasalsyndrome','progressivecorticobasalsyndrome'}
        lab = 'PC';
    case {'psppc','pcpsp','psppccombined','psppcgroup','pcpspcombined'}
        lab = 'PSPPC_EXCLUDED';
    case {'patient','patients','pooledpatient','pooledpatients'}
        lab = 'PATIENT';
    otherwise
        if contains(s, 'psp') && ~contains(s, 'pc')
            lab = 'PSP';
        elseif contains(s, 'pc') || contains(s, 'corticobasal')
            lab = 'PC';
        elseif contains(s, 'patient')
            lab = 'PATIENT';
        else
            lab = strtrim(raw);
        end
end
end

function labels = canonicalize_group_list(labelsIn)
% Convert labels from report Summary sheets to canonical PSP-only labels.
% "Patient" is expanded to bvFTD+PSP. 
labels = {};
for ii = 1:numel(labelsIn)
    lab = canonical_group_label(labelsIn{ii});
    if isempty(lab)
        continue;
    end

    if strcmp(lab, 'PATIENT')
        labels = [labels, {'bvFTD','PSP'}]; %#ok<AGROW>
    else
        labels = [labels, {lab}]; %#ok<AGROW>
    end
end
labels = unique(labels, 'stable');
end

function tf = is_legacy_pc_report(name)
s = lower(char(name));
s = regexprep(s, '[^a-z0-9]', '');
tf = contains(s, 'pcpsp') || contains(s, 'psppc');
end

function print_group_counts(labels)
labels = labels(:);
fprintf('\nCanonical group counts after PSP-only subject filtering:\n');
wanted = {'CON','PSP','bvFTD'};
for ii = 1:numel(wanted)
    fprintf('  %s : n = %d\n', wanted{ii}, sum(strcmp(labels, wanted{ii})));
end
end


function labels = parse_group_labels(s)
s = strtrim(s);
parts = regexp(s, ',', 'split');
parts = cellfun(@strtrim, parts, 'UniformOutput', false);
parts = parts(~cellfun(@isempty, parts));
labels = parts(:)';
end

function T = clean_stats_table(T)
requiredVars = {'ParamIndex','ParamName','p_uncorrected','Cohens_d'};
for i = 1:numel(requiredVars)
    if ~ismember(requiredVars{i}, T.Properties.VariableNames)
        warning('Stats table missing variable: %s', requiredVars{i});
        T = table;
        return;
    end
end

bad = ismissing(T.ParamName) | isnan(T.p_uncorrected) | isnan(T.Cohens_d);
T = T(~bad,:);

T = T(T.p_uncorrected > 0,:);
end

function z = safe_zscore(x)
x = x(:);
mu = mean(x, 'omitnan');
sd = std(x, 0, 'omitnan');
if isnan(sd) || sd == 0
    z = zeros(size(x));
else
    z = (x - mu) ./ sd;
end
end

function featIdx = rank_select(idxRef, score, K, direction)
score = score(:);
idxRef = idxRef(:);

valid = ~isnan(score) & ~isnan(idxRef);
score = score(valid);
idxRef = idxRef(valid);

if isempty(score)
    featIdx = [];
    return;
end

switch lower(direction)
    case 'descend'
        [~, ord] = sort(score, 'descend', 'MissingPlacement', 'last');
    otherwise
        [~, ord] = sort(score, 'ascend', 'MissingPlacement', 'last');
end

ord = ord(1:min(K, numel(ord)));
featIdx = idxRef(ord);
end

function [metricsTable, predTable, rocStruct] = run_models_loo( ...
    X, Y, yText, subjIDs, panelName, compName, g1, g2, rngSeed, nTreesRF, nTreesAda)

rng(rngSeed);

cvp = cvpartition(Y, 'LeaveOut');
nFolds = cvp.NumTestSets;

modelNames = {'LinearSVM','RBFSVM','RandomForest','AdaBoost'};

metricsTable = table();
predTable = table();
rocStruct = struct();

for m = 1:numel(modelNames)
    modelName = modelNames{m};

    yTrue  = nan(numel(Y),1);
    yPred  = nan(numel(Y),1);
    yScore = nan(numel(Y),1);

    for fold = 1:nFolds
        trIdx = training(cvp, fold);
        teIdx = test(cvp, fold);

        Xtr = X(trIdx,:);
        Xte = X(teIdx,:);
        Ytr = Y(trIdx);
        Yte = Y(teIdx);

        if numel(unique(Ytr)) < 2
            yTrue(teIdx)  = Yte;
            yPred(teIdx)  = mode(Ytr);
            yScore(teIdx) = double(mode(Ytr));
            continue;
        end

        mu = mean(Xtr, 1);
        sd = std(Xtr, 0, 1);
        sd(sd==0) = 1;

        Xtrz = (Xtr - mu) ./ sd;
        Xtez = (Xte - mu) ./ sd;

        switch modelName
            case 'LinearSVM'
                mdl = fitcsvm(Xtrz, Ytr, ...
                    'KernelFunction', 'linear', ...
                    'Standardize', false, ...
                    'ClassNames', [0 1], ...
                    'BoxConstraint', 1);
                mdl = fitPosterior(mdl);
                [pred, score] = predict(mdl, Xtez);
                posScore = get_positive_score(score);

            case 'RBFSVM'
                mdl = fitcsvm(Xtrz, Ytr, ...
                    'KernelFunction', 'rbf', ...
                    'KernelScale', 'auto', ...
                    'Standardize', false, ...
                    'ClassNames', [0 1], ...
                    'BoxConstraint', 1);
                mdl = fitPosterior(mdl);
                [pred, score] = predict(mdl, Xtez);
                posScore = get_positive_score(score);

            case 'RandomForest'
                mdl = TreeBagger(nTreesRF, Xtr, Ytr, ...
                    'Method', 'classification', ...
                    'OOBPrediction', 'off', ...
                    'MinLeafSize', 1, ...
                    'NumPredictorsToSample', 'all');
                [predCell, score] = predict(mdl, Xte);
                pred = str2double(predCell);

                classNamesRF = mdl.ClassNames;
                if iscell(classNamesRF)
                    posCol = find(strcmp(classNamesRF, '1'), 1);
                    if isempty(posCol), posCol = size(score,2); end
                else
                    posCol = find(classNamesRF == 1, 1);
                    if isempty(posCol), posCol = size(score,2); end
                end
                posScore = score(:, posCol);

            case 'AdaBoost'
                t = templateTree('MaxNumSplits', 20);
                mdl = fitcensemble(Xtr, Ytr, ...
                    'Method', 'AdaBoostM1', ...
                    'Learners', t, ...
                    'NumLearningCycles', nTreesAda);
                [pred, score] = predict(mdl, Xte);
                posScore = get_positive_score(score);
        end

        yTrue(teIdx)  = Yte;
        yPred(teIdx)  = pred;
        yScore(teIdx) = posScore;
    end

    valid = ~isnan(yTrue) & ~isnan(yPred) & ~isnan(yScore);
    yTrue_v  = yTrue(valid);
    yPred_v  = yPred(valid);
    yScore_v = yScore(valid);

    M = compute_binary_metrics(yTrue_v, yPred_v, yScore_v);
    M.Model = {modelName};
    M.NumEvaluated = numel(yTrue_v);

    metricsTable = [metricsTable; struct2table(M)];

    Tpred = table;
    Tpred.SubjectID          = subjIDs(:);
    Tpred.GroupText          = yText(:);
    Tpred.TrueLabel          = yTrue;
    Tpred.PredictedLabel     = yPred;
    Tpred.Score_Positive     = yScore;
    Tpred.CorrectPrediction  = (yTrue == yPred);
    Tpred.Model              = repmat({modelName}, numel(Y), 1);
    Tpred.Comparison         = repmat({compName}, numel(Y), 1);
    Tpred.Panel              = repmat({panelName}, numel(Y), 1);
    Tpred.Group1Label        = repmat({strjoin(g1, ',')}, numel(Y), 1);
    Tpred.Group2Label        = repmat({strjoin(g2, ',')}, numel(Y), 1);

    predTable = [predTable; Tpred];

    [fpr, tpr, ~, auc] = perfcurve(yTrue_v, yScore_v, 1);
    rocStruct.(modelName).fpr = fpr;
    rocStruct.(modelName).tpr = tpr;
    rocStruct.(modelName).auc = auc;
end
end

function posScore = get_positive_score(score)
if size(score,2) >= 2
    posScore = score(:,2);
else
    posScore = score(:,1);
end
end

function M = compute_binary_metrics(yTrue, yPred, yScore)

yTrue = yTrue(:);
yPred = yPred(:);
yScore = yScore(:);

TP = sum((yTrue==1) & (yPred==1));
TN = sum((yTrue==0) & (yPred==0));
FP = sum((yTrue==0) & (yPred==1));
FN = sum((yTrue==1) & (yPred==0));

acc = (TP + TN) / numel(yTrue);

if (TP+FN) > 0
    sens = TP / (TP + FN);
else
    sens = NaN;
end

if (TN+FP) > 0
    spec = TN / (TN + FP);
else
    spec = NaN;
end

if (TP+FP) > 0
    prec = TP / (TP + FP);
else
    prec = NaN;
end

if (prec + sens) > 0
    f1 = 2 * prec * sens / (prec + sens);
else
    f1 = NaN;
end

if (TP+FP) > 0 && (TP+FN) > 0 && (TN+FP) > 0 && (TN+FN) > 0
    mcc = ((TP*TN) - (FP*FN)) / sqrt((TP+FP)*(TP+FN)*(TN+FP)*(TN+FN));
else
    mcc = NaN;
end

try
    [~,~,~,auc] = perfcurve(yTrue, yScore, 1);
catch
    auc = NaN;
end

M = struct();
M.Accuracy    = acc;
M.Sensitivity = sens;
M.Specificity = spec;
M.Precision   = prec;
M.F1score     = f1;
M.MCC         = mcc;
M.AUC         = auc;
M.TP          = TP;
M.TN          = TN;
M.FP          = FP;
M.FN          = FN;
end

function save_roc_and_confusion_figures(rocStruct, predTable, figDir, panelName, compName)

modelNames = fieldnames(rocStruct);

for i = 1:numel(modelNames)
    modelName = modelNames{i};

    h = figure('Color','w','Position',[100 100 700 550],'Visible','off');
    plot(rocStruct.(modelName).fpr, rocStruct.(modelName).tpr, 'LineWidth', 2); hold on;
    plot([0 1], [0 1], '--k', 'LineWidth', 1.2);
    xlabel('False Positive Rate');
    ylabel('True Positive Rate');
    title(sprintf('%s | %s | AUC = %.3f', compName, modelName, rocStruct.(modelName).auc), ...
        'Interpreter','none');
    grid off; axis square;
    saveas(h, fullfile(figDir, sprintf('ROC_%s.png', modelName)));
    close(h);

    idx = strcmp(predTable.Model, modelName);
    yTrue = predTable.TrueLabel(idx);
    yPred = predTable.PredictedLabel(idx);

    valid = ~isnan(yTrue) & ~isnan(yPred);
    yTrue = yTrue(valid);
    yPred = yPred(valid);

    h2 = figure('Color','w','Position',[100 100 600 500],'Visible','off');
    cm = confusionchart(yTrue, yPred, ...
        'RowSummary','row-normalized', ...
        'ColumnSummary','column-normalized');
    cm.Title = sprintf('%s | %s | %s', compName, panelName, modelName);
    saveas(h2, fullfile(figDir, sprintf('Confusion_%s.png', modelName)));
    close(h2);
end

h3 = figure('Color','w','Position',[100 100 750 600],'Visible','off'); hold on;
for i = 1:numel(modelNames)
    modelName = modelNames{i};
    plot(rocStruct.(modelName).fpr, rocStruct.(modelName).tpr, ...
        'LineWidth', 2, ...
        'DisplayName', sprintf('%s (AUC=%.3f)', modelName, rocStruct.(modelName).auc));
end
plot([0 1],[0 1],'--k','HandleVisibility','off');
xlabel('False Positive Rate');
ylabel('True Positive Rate');
title(sprintf('%s | %s | ROC comparison', compName, panelName), 'Interpreter', 'none');
legend('Location','southeast');
grid off; axis square;
saveas(h3, fullfile(figDir, 'ROC_AllModels.png'));
close(h3);

end

function s = safe_sheet_name(s)
s = regexprep(s, '[:\\/?*\[\]]', '_');
if numel(s) > 31
    s = s(1:31);
end
end
